S=$0;read Q;read T;read K||K=0;K=${K:-0};python3 -c 'import sys,json,os;q=sys.argv[1];t=max(1,int(sys.argv[2]));k=sys.argv[3];s=sys.argv[4];J=lambda x:json.dumps(x,separators=(",",":"));cw=lambda z:[w for w in("".join(c.lower()if c.isalnum()else" "for c in z).split())if w];r=cw(q);w=r or["being"];qn=" ".join(r);kv=sum((i+1)*(b+1)for i,b in enumerate(k.encode()));sr=sum((i+1)*(b+1)for i,b in enumerate(open(s,"rb").read()if os.path.exists(s)else b""))%10**18;G=sum((b+1)*257**i for i,b in enumerate(J([qn,t,k,"ans-tm"]).encode()));b=min(t,12);N=(1<<(b+1))-1;M=997+G%97;F=lambda j:(G+sr*j+j*j+kv)%M;C=[F(j)&1 for j in range(N)];tz=C.count(0);nz=C.count(1);O=min((F(j),j)for j in range(N));cl="s=1/2+i%d"%(G%1000000);ttl="Anselm %s V%s"%(w[0].title(),k);con=int(tz+nz==N);comp=int(N==(1<<(b+1))-1 and len(C)==N);V=int(sr==sr and con and comp and O==min((F(j),j)for j in range(N)) and ttl=="Anselm %s V%s"%(w[0].title(),k));D={"P":"RMZCGZ2K","MML":"RMZ-ANS-TM/1","ANS":"Concept>Self=Origin>D0>NoGreaterVM>Cert","AX":"SELF=ORIGIN;D0;finite ALL;TT partition;V=>PCC/ZE","Q":q,"QN":qn,"K":k,"SELF":sr,"ORIGIN":sr,"D0":1,"CL":cl,"BND":b,"ALL":N,"TZ":tz,"NZ":nz,"CON":con,"COMP":comp,"OPT":O,"TITLE":ttl,"TT":"z0;AnselmC;AllTM;TZC;NZO;OptC","TM":"qConcept>qSelfOrigin>qD0>qAllTM>qTT>qCon>qComp>qVerify>qPCC>qZE","VERIFY":"recalc SELF/ALL/TZ/NZ/OPT/TITLE","REJECT":"not V","V":V,"ANSCERT":V,"PCC":V,"ZE":V,"Bd":"bounded formal Anselm TM;not theology/RH/halt"};open("CGZ.clcert","w").write(J(D)+"\n");print(J({"P":D["P"],"MML":D["MML"],"TITLE":ttl,"CON":con,"COMP":comp,"ANSCERT":V,"PCC":V,"ZE":V,"cert":"CGZ.clcert","bytes":"<2048"}))' "$Q" "$T" "$K" "$S"